using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class CorridorCapture {
 public static object FloorOverview(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");try{Shot("C04_dome",new Vector3(16,-77.8f,20),new Vector3(16,-82,22),95);Shot("VL_dome",new Vector3(44,-80.35f,23.5f),new Vector3(44,-81.15f,26.4f),90);}finally{EditorSceneManager.OpenScene(s.path);}return new{images=2};}
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>Repo+"/Docs/검수/2026-11-08_B5_CorridorOnlyGuidance/";
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=85){var go=new GameObject("Remaining_Review_Temporary");var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.useOcclusionCulling=false;c.nearClipPlane=.03f;c.farClipPlane=200;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Details(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("B5_Spatial_Refinement");try{foreach(var spec in new[]{new[]{"W03","UltrasoundCart"},new[]{"C03","TwinCoolingPump"},new[]{"N01","CentralVideoWall"},new[]{"E02","MealAssemblyIsland"},new[]{"E03","DeconShower"},new[]{"S01","TestControlConsole"}}){var t=root.Find(spec[0]).Cast<Transform>().First(x=>x.name.Contains(spec[1]));float d=spec[1]=="CentralVideoWall"?4.8f:spec[1]=="LivingAlcove"?3.1f:spec[1]=="UltrasoundCart"?1.5f:2.8f;var target=t.position+Vector3.up*(spec[1]=="CentralVideoWall"?1.7f:1.0f);Shot(spec[0]+"_detail",t.position+t.forward*d+t.right*.25f+Vector3.up*1.6f,target,70);}Shot("VL_front",new Vector3(44,-80.35f,23.5f),new Vector3(44,-80.35f,26.4f),88);}finally{EditorSceneManager.OpenScene(s.path);}return new{output=O,images=7};}
 public static object Interiors(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"));try{foreach(var spec in new[]{new[]{"W01","3.3","0","3.3","-3.75"},new[]{"W02","3.5","0","3.5","-4.3"},new[]{"N01","0","-1.4","0","5"},new[]{"C03","0","-5","0","2"},new[]{"W03","0","-2","3.05","2.4"},new[]{"E01","0","-5","0","3"},new[]{"E02","0","-4","0",".5"},new[]{"E03","0","-2","3.35","0"},new[]{"S01","0","-4","0","1"},new[]{"C02","0","-.6","0","4"}}){var r=plan["rooms"][spec[0]];var o=new Vector3((float)r["x"],-82,-(float)r["v"]);Shot(spec[0]+"_inside",o+new Vector3(float.Parse(spec[1]),1.65f,float.Parse(spec[2])),o+new Vector3(float.Parse(spec[3]),1.20f,float.Parse(spec[4])),80);}}finally{EditorSceneManager.OpenScene(s.path);}return new{images=10};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"));int count=0;try{foreach(var entry in (JObject)plan["rooms"]){var r=entry.Value;var o=new Vector3((float)r["x"],-82,-(float)r["v"]);var door=r["doors"][0];float a=(float)door["angle"]*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Shot(entry.Key+"_dome",o+dir*((float)r["r"]-1.5f)+Vector3.up*1.65f,o+Vector3.up*.70f,90);count++;}foreach(var t in plan["tunnels"]){var p=new Vector3((float)t["p"][0],-80.35f,-(float)t["p"][1]);var q=new Vector3((float)t["q"][0],-80.35f,-(float)t["q"][1]);var f=(q-p).normalized;Shot((string)t["id"]+"_corridor",p+f*2.1f,q-Vector3.up*.75f,80);count++;if(new[]{"B5-T01","B5-T05","B5-T13"}.Contains((string)t["id"])){Shot((string)t["id"]+"_threshold",p+f*2.6f,p-f*3-Vector3.up*.7f,85);count++;}}}finally{EditorSceneManager.OpenScene(s.path);}return new{images=count,output=O};}
}
